WITH Base AS (SELECT * FROM transactions WHERE account_id IN (3, 12, 38, 39)), transactions_stats AS (SELECT txn_type, CASE WHEN amount >= 3700 THEN 'high' WHEN amount >= 1200 THEN 'mid' ELSE 'low' END AS amount_bucket, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, MAX(txn_time) AS last_txn_time FROM Base GROUP BY txn_type, CASE WHEN amount >= 3700 THEN 'high' WHEN amount >= 1200 THEN 'mid' ELSE 'low' END) SELECT * FROM transactions_stats ORDER BY txn_type, last_txn_time
